#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

function fail(code) {
  throw new Error(`ATENDIMENTO_CRM_CORE_BACKFILL_BINDING_${code}`);
}

function object(value, code) {
  if (!value || typeof value !== "object" || Array.isArray(value)) fail(code);
  return value;
}

function readJson(file, code) {
  try {
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    fail(code);
  }
}

/**
 * The receipt signature establishes that the root-owned helper emitted the
 * data. This separate equality check establishes that the signed receipt is
 * for the exact one-use authorization generated by this workflow run.
 */
export function assertAtendimentoCrmCoreProjectionBackfillBinding({ authorization, receipt } = {}) {
  const expected = object(authorization, "AUTHORIZATION_INVALID");
  const actual = object(receipt, "RECEIPT_INVALID");
  const target = object(actual.target, "RECEIPT_TARGET_INVALID");
  const bindings = [
    [actual.receiptId, expected.authorizationId],
    [actual.authorizationId, expected.authorizationId],
    [actual.workflowRunId, expected.workflowRunId],
    [actual.runAttempt, expected.runAttempt],
    [actual.sourceSha, expected.sourceSha],
    [actual.admissionPlanSha256, expected.admissionPlanSha256],
    [target.repository, expected.coreRepository],
    [target.repositoryId, expected.coreRepositoryId],
    [target.release, expected.coreReleaseSha],
    [target.artifactDigest, expected.coreArtifactDigest],
    [target.artifactRunId, expected.coreArtifactRunId],
    [target.readbackDigest, expected.coreReadbackDigest],
    [target.readbackRunId, expected.coreReadbackRunId],
  ];
  if (bindings.some(([actualValue, expectedValue]) => actualValue !== expectedValue)) {
    fail("RECEIPT_AUTHORIZATION_MISMATCH");
  }
  return true;
}

export function assertAtendimentoCrmCoreProjectionBackfillBindingFiles(authorizationFile, receiptFile) {
  return assertAtendimentoCrmCoreProjectionBackfillBinding({
    authorization: readJson(authorizationFile, "AUTHORIZATION_JSON_INVALID"),
    receipt: readJson(receiptFile, "RECEIPT_JSON_INVALID"),
  });
}

const invokedAsScript = process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href;
if (invokedAsScript) {
  try {
    if (process.argv.length !== 5 || process.argv[2] !== "validate") fail("USAGE_INVALID");
    assertAtendimentoCrmCoreProjectionBackfillBindingFiles(process.argv[3], process.argv[4]);
    process.stdout.write("ATENDIMENTO_CRM_CORE_BACKFILL_BINDING_VALID\n");
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : "ATENDIMENTO_CRM_CORE_BACKFILL_BINDING_INVALID"}\n`);
    process.exitCode = 2;
  }
}
